simperBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "simperBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "miso",
                name = "simper",
                version = c(1,0,0),
                options = options,
                results = simperResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' SIMPER
#'
#' Describes how individual features contribute to average Bray-Curtis
#' dissimilarity between groups using vegan::simper. Optional permutation
#' results are exploratory rather than an overall group test.
#' @section References:
#' Oksanen et al. (2026). vegan: Community Ecology Package (R package version 2.7-5). https://vegandevs.github.io/vegan/
#'
#' Clarke, K. R. (1993). Non-parametric multivariate analyses of changes in community structure. Australian Journal of Ecology, 18(1), 117-143. https://doi.org/10.1111/j.1442-9993.1993.tb00438.x
#'
#' @param data .
#' @param vars .
#' @param factor .
#' @param transform .
#' @param distance .
#' @param distBinary .
#' @param seed .
#' @param simperN .
#' @param simperTop .
#' @param simperCum .
#' @param simperPlots .
#' @param simperHeatmap .
#' @param simperAssess .
#' @param simperAdjust .
#' @param simperDetails .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guidance} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$warnings} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$contrasts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$contributions} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$variability} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$means} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$table} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$contributionPlots} \tab \tab \tab \tab \tab an array of groups \cr
#'   \code{results$heatmapDescription} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$heatmap} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$heatmapValues} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$assessment} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$contrasts$asDF}
#'
#' \code{as.data.frame(results$contrasts)}
#'
#' @export
simper <- function(
    data,
    vars,
    factor,
    transform = "none",
    distance = "bray",
    distBinary = FALSE,
    seed = 0,
    simperN = 999,
    simperTop = 10,
    simperCum = 70,
    simperPlots = FALSE,
    simperHeatmap = FALSE,
    simperAssess = FALSE,
    simperAdjust = "holm",
    simperDetails = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("simper requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if ( ! missing(factor)) factor <- jmvcore::resolveQuo(jmvcore::enquo(factor))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL),
            `if`( ! missing(factor), factor, NULL))

    for (v in factor) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- simperOptions$new(
        vars = vars,
        factor = factor,
        transform = transform,
        distance = distance,
        distBinary = distBinary,
        seed = seed,
        simperN = simperN,
        simperTop = simperTop,
        simperCum = simperCum,
        simperPlots = simperPlots,
        simperHeatmap = simperHeatmap,
        simperAssess = simperAssess,
        simperAdjust = simperAdjust,
        simperDetails = simperDetails)

    analysis <- simperClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}
